n = len(unit)

pair = [-1]*n
stack = []
for i,c in enumerate(unit):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pair[j] = i
        pair[i] = j

# Map positions to hairpin loops (already from analyze_target)
# loops: [9,12] len4 close(8,13); [29,31] len3 close(28,32); [52,55] len4 close(51,56);
#        [65,68] len4 close(64,69); [80,83] len4 close(79,84)
# caps: GAAA/UUCG for len4; for len3 use GAA/GUA/UUU/CUU

# Hairpin loop assignments (loop interior positions, closing pair)
loops_info = [
    ([9,10,11,12], (8,13), "GAAA"),   # close with C-G: pos8=C, pos13=G
    ([29,30,31], (28,32), "GAA"),     # triloop
    ([52,53,54,55], (51,56), "UUCG"), # close C-G
    ([65,66,67,68], (64,69), "GAAA"), # close C-G
    ([80,81,82,83], (79,84), "UUCG"), # close C-G
]

def init_seq():
    seq = ['A']*n
    # assign all pairs as G-C by default (strong)
    for i in range(n):
        if pair[i]!=-1 and i<pair[i]:
            seq[i]='G'; seq[pair[i]]='C'
    return seq

def apply_caps(seq):
    s = seq[:]
    for loop_pos, (ci,cj), cap in loops_info:
        # closing pair: ci gets C, cj gets G (so ci..cj = C...G)
        s[ci]='C'; s[cj]='G'
        for k,pos in enumerate(loop_pos):
            s[pos]=cap[k]
    return s

def fold(seq):
    fc = RNA.fold_compound(seq)
    ss, mfe = fc.mfe()
    return ss, mfe

def bp_dist(ss, tgt):
    return RNA.bp_distance(ss, tgt)

# Repair loop: given current seq, fold, find spurious & missing pairs, fix targeted
def get_pairs(ss):
    p=[-1]*len(ss); st=[]
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); p[j]=i; p[i]=j
    return p

def repair_iter(seq, tgt):
    ss, mfe = fold(seq)
    if ss==tgt:
        return seq, ss, 0, True
    tp = get_pairs(tgt)
    fp = get_pairs(ss)
    s = seq[:]
    changed=0
    # Missing target pairs: strengthen to G-C
    for i in range(n):
        if tp[i]!=-1 and i<tp[i]:
            j=tp[i]
            if fp[i]!=j:
                # pair (i,j) missing in fold -> make strong G-C
                if s[i]!='G': s[i]='G'; changed+=1
                if s[j]!='C': s[j]='C'; changed+=1
    # Spurious pairs: break with mismatch
    for i in range(n):
        if fp[i]!=-1 and i<fp[i]:
            j=fp[i]
            if tp[i]!=j:
                # spurious (i,j): introduce mismatch - set j to A (if i is G/C) etc
                # choose to break by making one of them a mismatch
                # keep i, change j to non-complement of s[i]
                comp={'G':'C','C':'G','A':'U','U':'A'}
                # set j so it doesn't pair with i: pick a base != complement(s[i]) and != current if possible
                avoid = comp.get(s[i],'A')
                choices=[b for b in 'ACGU' if b!=avoid]
                # prefer A (weak) 
                new = 'A' if 'A' in choices else choices[0]
                if s[j]!=new:
                    s[j]=new; changed+=1
    return s, ss, bp_dist(ss,tgt), False

# Main: start from capped init, repair
