                # alternate GC/CG/AU
                choice=random.choice([('G','C'),('C','G'),('G','U'),('A','U')])
                seq[i]=choice[0]; seq[pair[i]]=choice[1]
        seq = apply_caps(seq)  # re-apply caps (may override some)
    # iterate repair
    cur = seq[:]
