            break
        if d<best_d:
            best_d=d; best_seq=cur[:]; best_ss=ss
    if d==0:
        best_d=0; best_seq=cur[:]; best_ss=unit
        print(f"restart {restart}: SOLVED")
        break
    if restart%5==0:
        print(f"restart {restart}: best_d={best_d}")

print("BEST_DIST", best_d)
print("BEST_SEQ", best_seq)
if best_ss:
    print("BEST_SS", best_ss)
    print("TGT   ", unit)
    print("MATCH", best_ss==unit)
